SELECT
*
FROM (
SELECT
*,
ROW_NUMBER() OVER (PARTITION BY collaborate_material ORDER BY create_time DESC) AS rn
FROM ${tableName}
WHERE collaborate_material IN

    #{collaborateMaterial}

AND collaborate_type = #{collaborateType}

    AND process IN

        #{processCondition}


AND enterprise_code = #{enterpriseCode}
) t
WHERE rn = 1

SELECT *
FROM (SELECT *,
SUM(schedule_item) OVER (PARTITION BY same_material_merge_flag) AS scheduleItem,
ROW_NUMBER() OVER (
PARTITION BY same_material_merge_flag
ORDER BY create_time DESC
) AS rn
FROM ${tableName}
WHERE delete_flag = false
AND enterprise_code = #{enterpriseCode}
AND collaborate_material = #{collaborateMaterial}
AND collaborate_type = #{collaborateType}

    AND process IN

        #{processCondition}


) t
WHERE t.rn = 1
ORDER BY t.create_time DESC
